func TestFilesService_Add_RetriesOn429WithOSFile(t *testing.T) {
	t.Parallel()

	tmpFile, err := os.CreateTemp(t.TempDir(), "upload-*.txt")
	if err != nil {
		t.Fatalf("create temp file: %v", err)
	}
	payload := "document content to be uploaded"
	if _, err := tmpFile.WriteString(payload); err != nil {
		t.Fatalf("write temp file: %v", err)
	}
	if err := tmpFile.Close(); err != nil {
		t.Fatalf("close temp file: %v", err)
	}

	var attempts int
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts:     3,
			BaseDelay:       1 * time.Millisecond,
			MaxDelay:        5 * time.Millisecond,
			RetryAllMethods: true,
			Jitter:          func(d time.Duration) time.Duration { return d },
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		attempts++
		if attempts == 1 {
			w.Header().Set("Retry-After", "0")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"Rate limit reached"}`))
			return
		}

		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("attempt %d: parse multipart form: %v", attempts, err)
		}
		file, header, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("attempt %d: get form file: %v", attempts, err)
		}
		defer file.Close()

		if header.Filename != "document.txt" {
			t.Fatalf("attempt %d: unexpected filename: %q", attempts, header.Filename)
		}
		content, err := io.ReadAll(file)
		if err != nil {
			t.Fatalf("attempt %d: read form file: %v", attempts, err)
		}
		if string(content) != payload {
			t.Fatalf("attempt %d: unexpected content: %q", attempts, string(content))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":99,"name":"document.txt"}}`))
	})

	f, err := os.Open(tmpFile.Name())
	if err != nil {
		t.Fatalf("open temp file: %v", err)
	}
	defer f.Close()

	file, err := client.Files.Add(context.Background(), "document.txt", f)
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if attempts != 2 {
		t.Fatalf("expected 2 attempts, got %d", attempts)
	}
	if file.ID != 99 || file.Name != "document.txt" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

